// subscribeMonthly starts a monthly licensed subscription of Acme for a customer with pm as payment method.
func subscribeMonthly(t *testing.T, e *apitest.Env, c store.Customer, pm string) store.Subscription {
	t.Helper()
	setPaymentMethod(e, e.Acme.ID, c, pm)
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
