}

func TestRenewDueGoesOnPastAFailure(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	down := e.CreateCustomer(e.Acme, "Down", "down@example.com")
	failing := subscribeMonthly(t, e, down, "pm_card_visa")
	setPaymentMethod(e, e.Acme.ID, down, "pm_gateway_down")
	up := e.CreateCustomer(e.Acme, "Up", "up@example.com")
	working := subscribeMonthly(t, e, up, "pm_card_visa")
	e.Clock.Set(working.CurrentPeriodEnd)
	n, err := e.Subs.RenewDue(ctx)
	if n != 2 || !errors.Is(err, payments.ErrUnavailable) {
