// setPaymentMethod sets a customer's default payment method.
func setPaymentMethod(e *apitest.Env, orgID string, c store.Customer, pm string) {
	_, _ = e.Store.UpdateCustomer(orgID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = pm; return nil })
}

// subscribeMonthly starts a monthly licensed subscription of Acme for a customer with pm as payment method.
func subscribeMonthly(t *testing.T, e *apitest.Env, c store.Customer, pm string) store.Subscription {
	t.Helper()
	setPaymentMethod(e, e.Acme.ID, c, pm)
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

func TestRenewalDuringChargeInvoicesOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	sub := subscribeMonthly(t, e, c, "pm_card_visa")
	e.Clock.Set(sub.CurrentPeriodEnd)
	// While the renewal's charge is in flight, another instance runs RenewDue.
	var nested int
	var nestedErr error
	e.Gateway.OnCharge = func(payments.ChargeRequest) {
		if nested++; nested == 1 {
			nested, nestedErr = e.Subs.RenewDue(ctx)
			nested = 0
		}
	}
	n, err := e.Subs.RenewDue(ctx)
	if err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	if nestedErr != nil || nested != 0 {
		t.Fatalf("the other instance renewed = %d, %v", nested, nestedErr)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoicePaid {
		t.Fatalf("invoices = %+v, want the first and one paid renewal", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want 2 (first period and one renewal)", len(cs))
	}
}

func TestConcurrentRenewDueInvoicesOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	sub := subscribeMonthly(t, e, c, "pm_card_visa")
	e.Clock.Set(sub.CurrentPeriodEnd)
	var renewed atomic.Int64
	var wg sync.WaitGroup
	for range 8 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			n, err := e.Subs.RenewDue(ctx)
			if err != nil {
				t.Errorf("RenewDue: %v", err)
			}
			renewed.Add(int64(n))
		}()
	}
	wg.Wait()
	if renewed.Load() != 1 {
		t.Fatalf("renewed %d times, want once", renewed.Load())
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 {
		t.Fatalf("invoices = %d, want the first and one renewal", len(invs))
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want 2 (first period and one renewal)", len(cs))
	}
}

func TestGatewayDownRenewsOnceAndKeepsInvoiceOpen(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	sub := subscribeMonthly(t, e, c, "pm_card_visa")
	setPaymentMethod(e, e.Acme.ID, c, "pm_gateway_down")
	e.Clock.Set(sub.CurrentPeriodEnd)
	n, err := e.Subs.RenewDue(ctx)
	if n != 1 || !errors.Is(err, payments.ErrUnavailable) {
		t.Fatalf("RenewDue = %d, %v; want 1 renewed and ErrUnavailable", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("after the outage = %+v, want the next period and status active", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v, want an open renewal", invs)
	}
	calls := len(e.Gateway.Calls())

	// The gateway is back: the next run must not invoice or charge the period again.
	setPaymentMethod(e, e.Acme.ID, c, "pm_card_visa")
	if n, err := e.Subs.RenewDue(ctx); n != 0 || err != nil {
		t.Fatalf("RenewDue after recovery = %d, %v", n, err)
	}
	if len(e.Gateway.Calls()) != calls {
		t.Fatalf("the period was charged again")
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 {
		t.Fatalf("invoices = %d, want 2", len(invs))
	}
	// The open invoice is paid later, by hand.
	if _, _, err := e.Payments.Pay(ctx, e.Acme.ID, invs[1].ID, ""); err != nil {
		t.Fatal(err)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want 2", len(cs))
	}
}

func TestDeclinedRenewalIsPastDue(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	sub := subscribeMonthly(t, e, c, "pm_card_visa")
