		t.Fatalf("invoices = %+v, want an open renewal", invs)
	}
}

func TestRenewDueGoesOnPastAFailure(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	down := e.CreateCustomer(e.Acme, "Down", "down@example.com")
	failing := subscribeMonthly(t, e, down, "pm_card_visa")
