143	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
144	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
145	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
146	// due. An unavailable gateway leaves the invoice open and the subscription's status as it was. A period is renewed at most
147	// once, so RenewDue can run again, or in several instances at once, without invoicing a period twice. RenewDue goes on past
148	// a subscription that fails and returns the errors after trying them all. It returns how many subscriptions it renewed or
149	// canceled.
150	func (s *Service) RenewDue(ctx context.Context) (int, error) {
151		now := s.Clock.Now()
152		n := 0
153		var errs []error
154		for _, sub := range s.Store.DueSubscriptions(now) {
155			if err := ctx.Err(); err != nil {
156				return n, errors.Join(append(errs, err)...)
157			}
158			done, err := s.renew(ctx, sub, now)
159			if done {
160				n++
161			}
162			if err != nil {
163				errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
164			}
165		}
166		return n, errors.Join(errs...)
167	}
