169	// renew renews one subscription and reports whether this call renewed or canceled it. A call that finds the period already
170	// renewed by another one leaves it to that call: it reports false without an error.
171	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
172		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
173		if !ok {
174			return false, store.ErrNotFound
175		}
176		if sub.CancelAtPeriodEnd {
177			end := sub.CurrentPeriodEnd
178			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
179				x.Status, x.CanceledAt = store.Canceled, &end
180				return nil
181			})
182			if err == nil {
183				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
184			}
185			return err == nil, err
186		}
187		start := now
188		end := billing.AddInterval(start, plan.Interval)
189		var bill *store.Invoice
190		switch {
191		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
192			inv := s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
193			bill = &inv
194		case plan.UsageType == store.Licensed:
195			inv := s.periodInvoice(sub, plan, start, end)
196			bill = &inv
197		}
198		// The period moves on and its invoice is stored in one step, before anything is charged. A call that loses the race, or a
199		// later run, finds the period renewed and charges nothing. A failed charge leaves the invoice open.
200		next, inv, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, sub.CurrentPeriodStart, func(x *store.Subscription) error {
201			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
202			return nil
203		}, bill, now)
204		if errors.Is(err, store.ErrConflict) {
205			return false, nil
206		}
207		if err != nil {
208			return false, err
209		}
210		paid := true
211		var chargeErr error
212		if inv != nil {
213			s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
214			paid, chargeErr = s.chargeInvoice(ctx, *inv)
215		}
216		if chargeErr == nil {
217			want := store.Active
218			if !paid {
219				want = store.PastDue
220			}
221			next, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
222				if x.Status != store.Canceled {
223					x.Status = want
224				}
225				return nil
226			})
227			if err != nil {
228				return true, err
229			}
230		}
231		s.publish(ctx, sub.OrgID, "subscription.updated", next)
232		return true, chargeErr
233	}
