235	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
236	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
237	// payment method stays open and counts as paid here (it is paid by hand).
238	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
239		inv, err := s.Store.CreateInvoice(s.periodInvoice(sub, plan, start, end), s.Clock.Now())
240		if err != nil {
241			return false, err
242		}
243		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
244		return s.chargeInvoice(ctx, inv)
245	}
