247	// periodInvoice is the open invoice that bills one period of a subscription. It is not stored.
248	func (s *Service) periodInvoice(sub store.Subscription, plan store.Plan, start, end time.Time) store.Invoice {
249		var lines []store.Line
250		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
251		switch plan.UsageType {
252		case store.Licensed:
253			if plan.UnitAmount > 0 {
254				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
255			}
256		case store.Metered:
257			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
258				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
259			}
260		}
261		ps, pe := start, end
262		return store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
263			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}
264	}
