266	// chargeInvoice charges an open invoice to its customer's default payment method. It reports false when the charge was
267	// declined. Any other error means the gateway failed and nothing was taken; the invoice stays open.
268	func (s *Service) chargeInvoice(ctx context.Context, inv store.Invoice) (bool, error) {
269		_, _, err := s.Payments.Pay(ctx, inv.OrgID, inv.ID, "")
270		var decline *payments.DeclineError
271		switch {
272		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
273			return true, nil
274		case errors.As(err, &decline):
275			return false, nil
276		default:
277			return false, err
278		}
279	}
