176	// RenewSubscription renews a subscription in one step, so that each period is renewed at most once. It works only while the
177	// subscription is not canceled and is still in the period that starts at fromStart: then f sets its next period and, when
178	// inv is not nil, the invoice is stored as open in the same step. Otherwise it returns ErrConflict and changes nothing,
179	// because another renewal of that period got there first.
180	func (s *Store) RenewSubscription(orgID, id string, fromStart time.Time, f func(*Subscription) error, inv *Invoice, now time.Time) (Subscription, *Invoice, error) {
181		if inv != nil {
182			if err := checkInvoice(*inv); err != nil {
183				return Subscription{}, nil, err
184			}
185		}
186		s.mu.Lock()
187		defer s.mu.Unlock()
188		old, ok := s.subs[id]
189		if !ok || old.OrgID != orgID {
190			return Subscription{}, nil, ErrNotFound
191		}
192		if old.Status == Canceled || !old.CurrentPeriodStart.Equal(fromStart) {
193			return Subscription{}, nil, fmt.Errorf("%w: the subscription's period was already renewed", ErrConflict)
194		}
195		sub := copySub(old)
196		if err := f(&sub); err != nil {
197			return Subscription{}, nil, err
198		}
199		sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
200		if err := s.checkSubscription(sub); err != nil {
201			return Subscription{}, nil, err
202		}
203		var created *Invoice
204		if inv != nil {
205			c, err := s.createInvoice(*inv, now)
206			if err != nil {
207				return Subscription{}, nil, err
208			}
209			created = &c
210		}
211		s.subs[id] = sub
212		return copySub(sub), created, nil
213	}
