168		sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
169		if err := s.checkSubscription(sub); err != nil {
170			return Subscription{}, err
171		}
172		s.subs[id] = sub
173		return copySub(sub), nil
174	}
