215	// checkSubscription checks a changed subscription. The caller holds the lock.
216	func (s *Store) checkSubscription(sub Subscription) error {
217		if sub.Quantity <= 0 {
218			return invalid("the quantity must be at least 1")
219		}
220		if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != sub.OrgID {
221			return ErrNotFound
222		}
223		return nil
224	}
