226	// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
227	// canceled, the longest overdue first.
228	func (s *Store) DueSubscriptions(now time.Time) []Subscription {
229		s.mu.Lock()
230		defer s.mu.Unlock()
231		out := []Subscription{}
232		for _, sub := range s.subs {
233			if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
234				out = append(out, copySub(sub))
235			}
236		}
237		sort.Slice(out, func(i, j int) bool {
238			if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
239				return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
240			}
241			return out[i].ID < out[j].ID
242		})
243		return out
244	}
