246	func copySub(sub Subscription) Subscription {
247		if sub.TrialEnd != nil {
248			t := *sub.TrialEnd
249			sub.TrialEnd = &t
250		}
251		if sub.CanceledAt != nil {
252			t := *sub.CanceledAt
253			sub.CanceledAt = &t
254		}
255		return sub
256	}
