258	// AddUsage records usage of a subscription to a metered plan at time at.
259	func (s *Store) AddUsage(orgID, subID string, quantity int64, at, now time.Time) (UsageRecord, error) {
260		if quantity <= 0 {
261			return UsageRecord{}, invalid("usage must be a positive quantity")
262		}
263		s.mu.Lock()
264		defer s.mu.Unlock()
265		sub, ok := s.subs[subID]
266		if !ok || sub.OrgID != orgID {
267			return UsageRecord{}, ErrNotFound
268		}
269		if p := s.plans[sub.PlanID]; p.UsageType != Metered {
270			return UsageRecord{}, invalid("the subscription's plan is not metered")
271		}
272		u := UsageRecord{ID: s.newID("use"), OrgID: orgID, SubscriptionID: subID, Quantity: quantity, At: at.UTC(), CreatedAt: now.UTC()}
273		s.usage = append(s.usage, u)
274		return u, nil
275	}
