277	// UsageTotal adds up a subscription's usage at times in [from, to).
278	func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
279		s.mu.Lock()
280		defer s.mu.Unlock()
281		var n int64
282		for _, u := range s.usage {
283			if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
284				n += u.Quantity
285			}
286		}
287		return n
288	}
